"use client";

import { motion, useReducedMotion } from "framer-motion";

function ShimmerBlock({ className }: { className: string }) {
  return (
    <div className={`relative overflow-hidden rounded-md bg-slate-200 dark:bg-slate-700 ${className}`}>
      <motion.span
        aria-hidden
        className="absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/60 to-transparent dark:via-white/10"
        animate={{ x: ["-100%", "100%"] }}
        transition={{ duration: 1.4, repeat: Infinity, ease: "linear" }}
      />
    </div>
  );
}

export function SkeletonCard() {
  const shouldReduceMotion = useReducedMotion();

  if (shouldReduceMotion) {
    return (
      <div className="flex w-full max-w-sm items-center gap-4 rounded-2xl border border-slate-200 bg-white p-5 opacity-70 dark:border-slate-700 dark:bg-neutral-950">
        <div className="h-12 w-12 shrink-0 rounded-full bg-slate-200 dark:bg-slate-700" />
        <div className="flex flex-1 flex-col gap-2.5">
          <div className="h-3 w-3/4 rounded-md bg-slate-200 dark:bg-slate-700" />
          <div className="h-3 w-1/2 rounded-md bg-slate-200 dark:bg-slate-700" />
        </div>
      </div>
    );
  }

  return (
    <div role="status" aria-label="Loading content" className="flex w-full max-w-sm items-center gap-4 rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-700 dark:bg-neutral-950">
      <ShimmerBlock className="h-12 w-12 shrink-0 rounded-full" />
      <div className="flex flex-1 flex-col gap-2.5">
        <ShimmerBlock className="h-3 w-3/4" />
        <ShimmerBlock className="h-3 w-1/2" />
      </div>
    </div>
  );
}
